import os

for root, dirs, files in os.walk('.'):
    # Skip hidden dirs like .git and .codex internals for brevity
    dirs[:] = [d for d in dirs if not d.startswith('.')]
    level = root.count(os.sep)
    indent = '  ' * level
    print(f'{indent}{os.path.basename(root) or "."}/')
    for f in sorted(files):
        if f.startswith('.'):
            continue
        fp = os.path.join(root, f)
        try:
            size = os.path.getsize(fp)
        except OSError:
            size = -1
        print(f'{indent}  {f} ({size} bytes)')

import csv
import json

rows = []
with open('eu_economic_data.csv', newline='', encoding='utf-8') as f:
    reader = csv.DictReader(f)
    for r in reader:
        rows.append({
            'country': r['Country'],
            'year': int(r['Year']),
            'gdp': float(r['GDP_Billion_EUR']),
            'growth': float(r['GDP_Growth_Pct']),
            'unemp': float(r['Unemployment_Pct']),
            'infl': float(r['Inflation_Pct']),
            'trade': float(r['Trade_Balance_Billion_EUR']),
            'debt': float(r['Public_Debt_Pct_GDP']),
        })

by_key = {(r['country'], r['year']): r for r in rows}
countries = ['Germany', 'France', 'Italy', 'Spain', 'Netherlands', 'Poland', 'Sweden']
eu = {y: by_key[('EU_Total', y)] for y in (2022, 2023, 2024)}

out = {}

# EU-level story
g22, g24 = eu[2022]['gdp'], eu[2024]['gdp']
out['eu_gdp_nominal_change'] = round((g24 - g22) / g22 * 100, 1)
out['eu_gdp_2022_2024'] = (g22, g24)
out['eu_inflation'] = {y: eu[y]['infl'] for y in (2022, 2023, 2024)}
out['eu_trade'] = {y: eu[y]['trade'] for y in (2022, 2023, 2024)}
out['eu_debt'] = {y: eu[y]['debt'] for y in (2022, 2023, 2024)}
out['eu_unemp'] = {y: eu[y]['unemp'] for y in (2022, 2023, 2024)}
out['eu_growth'] = {y: eu[y]['growth'] for y in (2022, 2023, 2024)}

# Country-level stories
out['growth_2024_rank'] = sorted(countries, key=lambda c: by_key[(c, 2024)]['growth'], reverse=True)
out['gdp_2024_rank'] = sorted(countries, key=lambda c: by_key[(c, 2024)]['gdp'], reverse=True)
out['country_growth_2024'] = {c: by_key[(c, 2024)]['growth'] for c in countries}
out['country_inflation_2022'] = {c: by_key[(c, 2022)]['infl'] for c in countries}
out['country_inflation_2024'] = {c: by_key[(c, 2024)]['infl'] for c in countries}
out['country_trade_2024'] = {c: by_key[(c, 2024)]['trade'] for c in countries}
out['country_trade_2022'] = {c: by_key[(c, 2022)]['trade'] for c in countries}
out['country_unemp_2024'] = {c: by_key[(c, 2024)]['unemp'] for c in countries}
out['country_unemp_2022'] = {c: by_key[(c, 2022)]['unemp'] for c in countries}
out['country_debt_2024'] = {c: by_key[(c, 2024)]['debt'] for c in countries}
out['country_debt_2022'] = {c: by_key[(c, 2022)]['debt'] for c in countries}

# Italy trade swing
out['italy_trade_swing'] = round(by_key[('Italy', 2024)]['trade'] - by_key[('Italy', 2022)]['trade'], 1)

# Germany contraction
out['germany_growth_2024'] = by_key[('Germany', 2024)]['growth']

# Spain / Poland growth
out['spain_growth'] = {y: by_key[('Spain', y)]['growth'] for y in (2022, 2023, 2024)}
out['poland_growth'] = {y: by_key[('Poland', y)]['growth'] for y in (2022, 2023, 2024)}

# Netherlands surplus
out['nl_trade'] = {y: by_key[('Netherlands', y)]['trade'] for y in (2022, 2023, 2024)}

# Germany debt change
out['germany_debt'] = {y: by_key[('Germany', y)]['debt'] for y in (2022, 2023, 2024)}

# Unemployment champion/concern
out['unemp_min_2024'] = min(countries, key=lambda c: by_key[(c, 2024)]['unemp'])
out['unemp_max_2024'] = max(countries, key=lambda c: by_key[(c, 2024)]['unemp'])

# Inflation drop amplitude
out['infl_drop'] = {c: round(by_key[(c, 2022)]['infl'] - by_key[(c, 2024)]['infl'], 1) for c in countries}

# Debt levels 2024
out['debt_high_2024'] = sorted(countries, key=lambda c: by_key[(c, 2024)]['debt'], reverse=True)

print(json.dumps(out, indent=2, ensure_ascii=False))

